import React from "react";

import { MOCK_PROMPT_CARDS } from "@/components/prompts/prompt-mock-data";

/**
 * Mock cards grid — B design, cleaner final-card layout.
 *
 * Uniform card size with a fixed preview height (h-60): vertical
 * previews are cropped to that height, horizontal previews fill it.
 * The preview area is a plain token-coloured placeholder block — it
 * is NOT a real generation and is NOT claimed as generated by any
 * tool, and nothing is hotlinked or copied from a researched site.
 *
 * Cards are deliberately NON-interactive in this push: there is no
 * dedicated detail section yet, so clicking a card does nothing.
 * Cards are plain <article> elements — no button, no link, no
 * onClick, no modal, no navigation. They also carry NO master prompt
 * text, NO how-to steps, NO Show prompt toggle, and NO Copy button:
 * prompt + how-to live in the dedicated section, which is a later
 * step. Copied counts shown here are the mock data's layout
 * placeholders, not real usage.
 *
 * Design-system primitives + tokens only: no literal colours, no
 * inline styles.
 */
export function PromptMockCardGrid() {
  return (
    <section
      data-testid="prompt-mock-card-grid"
      aria-label="Prompt cards"
      className="bg-canvas px-4 pb-12 sm:px-6 sm:pb-16"
    >
      <div className="mx-auto grid w-full max-w-5xl grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
        {MOCK_PROMPT_CARDS.map((card) => (
          <article
            key={card.title}
            data-testid="prompt-mock-card"
            className="overflow-hidden rounded-2xl border border-line bg-panel shadow-card"
          >
            <div
              data-testid="prompt-mock-card-preview"
              className="flex h-60 items-end overflow-hidden bg-canvas p-3"
            >
              <span className="text-sm text-ink-sub">Preview</span>
            </div>
            <div className="p-4">
              <h3 className="text-lg font-bold leading-snug text-ink">{card.title}</h3>
              <p className="mt-2 text-sm leading-relaxed text-ink-sub">
                {card.shortDescription}
              </p>
              <p className="mt-3 text-sm text-ink-sub">
                <span className="font-semibold text-ink">{card.tool}</span>
                {` · ${card.category} · ${card.language} · ${card.length} · ${card.format}`}
              </p>
              <p className="mt-3 border-t border-line pt-3 text-sm text-ink-sub">
                {`Copied ${card.copiedCount} times · Added ${card.dateAdded}`}
              </p>
            </div>
          </article>
        ))}
      </div>
    </section>
  );
}
